// ── Reporting ──

/** This API endpoint provides reporting data to partners for aggregate common stock and crypto positions across their account base. Partners can view historical snapshots of their holding across their entire account base. Please note that this API utilizes an 8:00 pm (EST) cutoff which aligns with the end of the Securities extended hours trading session as well as Alpaca's 24 hour Crypto trading window. Additionally, the endpoint supports indexing to help the partner efficiently filter by key information including date and symbol while being able to include or remove firm accounts. */
export const getV1ReportingEodAggregatePositions = {
  name: "Retrieve Aggregate Positions",
  api: "broker",
  method: "GET",
  path: "v1/reporting/eod/aggregate_positions",

  params: Z.never(),
  query: Z.object({ date: Z.iso.date(), symbols: Z.string().optional(), firm_accounts: Z.string().optional() }),
  body: Z.never(),
  response: Z.array(S.AggregatePositionResponseSchema),

  okStatus: 200,
} satisfies Endpoint;

/** This API retrieves a list of cash interest details for the given date(s) for a single account or all accounts. End-of-day (EOD) details are typically accessible after 8:00pm Eastern Time (ET) and reflect that day's ending state across cash balances, accrued interest, accrued fees, as well as additional ancillary details. */
export const getV1GetEodCashInterestReport = {
  name: "Retrieve EOD Cash Interest Details",
  api: "broker",
  method: "GET",
  path: "v1/reporting/eod/cash_interest",

  params: Z.never(),
  query: Z.object({
    account_id: Z.string().optional(),
    date: Z.iso.date().optional(),
    after: Z.iso.date().optional(),
    before: Z.iso.date().optional(),
    direction: Z.string().optional(),
    page_size: Z.number().int().optional(),
    page_token: Z.string().optional(),
  }),
  body: Z.never(),
  response: S.EoDCashInterestReportResponseSchema,

  okStatus: 200,
} satisfies Endpoint;

/** This API retrieves a comprehensive list of end-of-day positions for all accounts. End-of-day (EOD) positions are typically accessible after 4:00 am Eastern Time (ET) on the following day, providing a comprehensive view of the day's closing positions across all accounts. This API currently only supports retrieving EOD positions for the last trading date. */
export const getV1ReportingEodPositions = {
  name: "Retrieve EOD Positions",
  api: "broker",
  method: "GET",
  path: "v1/reporting/eod/positions",

  params: Z.never(),
  query: Z.object({
    account_id: Z.string().optional(),
    asset: Z.string().optional(),
    asof: Z.iso.date().optional(),
    page_token: Z.string().optional(),
    limit: Z.number().int().optional(),
  }),
  body: Z.never(),
  response: Z.object({
    /** The date of the snapshot in the 'YYYY-MM-DD' format. */
    asof: Z.iso.date().optional(),
    next_page_token: S.NextPageTokenSchema.optional(),
    /** A detailed map of account IDs to their respective positions. */
    positions: Z.record(Z.string(), Z.array(S.PositionSchema)).optional(),
  }),

  okStatus: 200,
} satisfies Endpoint;

